 "content": "from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, x in comp)
            r1 = max(y for y, x in comp)
            c0 = min(x for y, x in comp)
            c1 = max(x for y, x in comp)
            top_gaps = [x for x in range(c0, c1 + 1) if grid[r0][x] == 0]
            # Fill the cavity and its single opening with color 2.
            for y in range(r0, r1 + 1):
                for x in range(c0, c1 + 1):
                    if grid[y][x] == 0:
                        out[y][x] = 2
            # Extend the opening horizontally toward the left edge.
            if r0 > 0 and top_gaps:
                gap = top_gaps[0]
                for x in range(gap + 1):
                    if grid[r0 - 1][x] == 0:
                        out[r0 - 1][x] = 2
    return out
